97	/// Bump a fence token (``` or ~~~), remapping if necessary.
98	fn bump_fence(p: &mut MarkdownParser, is_tilde_fence: bool) {
99	    if is_tilde_fence {
100	        if p.at(TRIPLE_TILDE) {
101	            p.bump(TRIPLE_TILDE);
102	        } else {
103	            p.bump_remap(TRIPLE_TILDE);
104	        }
105	    } else if p.at(T!["```"]) {
106	        p.bump(T!["```"]);
107	    } else {
108	        p.bump_remap(T!["```"]);
109	    }
110	}
