1423	fn scan_list_indent(p: &mut MarkdownParser, required_indent: usize) {
1424	    let mut consumed = 0usize;
1425	    while consumed < required_indent && p.at(MD_TEXTUAL_LITERAL) {
1426	        let text = p.cur_text();
1427	        if text.is_empty() || !text.chars().all(|c| c == ' ' || c == '\t') {
1428	            break;
1429	        }
1430	
1431	        let indent: usize = text
1432	            .chars()
1433	            .map(|c| if c == '\t' { TAB_STOP_SPACES } else { 1 })
1434	            .sum();
1435	
1436	        if consumed + indent > required_indent {
1437	            break;
1438	        }
1439	
1440	        consumed += indent;
1441	        p.bump(MD_TEXTUAL_LITERAL);
1442	    }
